       cmd = self._build_command(self.get_option('ssh_executable'), 'ssh', '-O', 'check', self.host)
       controlpersist, controlpath = self._persistence_controls(cmd)
       if controlpersist:
           p = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
           p.communicate()
           if p.wait() == 0:
               cmd[-2] = b'stop'
           else:
               display.debug(u'No persistent SSH connection to reset for %s' % self.host)
               self.close()
               return
           display.vvv(u'sending stop: %s' % to_text(cmd))
           p = subprocess.Popen(cmd, stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
           stdout, stderr = p.communicate()
           status_code = p.wait()
           if status_code != 0:
               display.warning(u"Failed to reset connection:%s" % to_text(stderr))
       else:
           display.debug(u'No persistent SSH connection to reset for %s' % self.host)

